const e=[{id:"sv-2-941",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"In Minitab output, which kurtosis value corresponds to the tail shape of a **normal** distribution?",options:["−3","0","1","3"],answer:1,hint:"Minitab reports excess kurtosis: the normal curve is the zero point.",steps:[{title:"Key idea",body:"Minitab (and Excel) subtract 3, so a normal curve scores **0**."},{title:"Apply to the stem",body:"Positive = heavier tails, negative = lighter tails than normal."}],final:"Normal shape = kurtosis 0 in Minitab → answer **B**",whyWrong:["Incorrect — −3 is not a reference value; it would mean an extremely flat, light-tailed shape.","","Incorrect — 1 is a mildly heavy-tailed (leptokurtic) shape, not the normal reference.","Incorrect — 3 is the normal value only in the 'raw' convention; Minitab subtracts 3 and reports excess kurtosis."],bookRef:"Book pp. 257–261",trap:"Some textbooks quote kurtosis = 3 for a normal curve; Minitab output has already removed the 3."},{id:"sv-2-942",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"How is the **direction** of skewness named?",options:["By the side on which the peak of the data lies","By whether the mean is above or below the mode","By whether the kurtosis is positive or negative","By the side on which the long tail lies"],answer:3,hint:"Skew follows the tail, not the hump.",steps:[{title:"Key idea",body:"A long tail of high values = right (positive) skew; a long tail of low values = left (negative) skew."},{title:"Eliminate look-alikes",body:"The hump is on the other side, so naming by the peak is the classic trap."}],final:"Skew is named after the tail → answer **D**",whyWrong:["Incorrect — the peak sits on the opposite side to the tail; naming by the peak reverses the direction.","Incorrect — mean versus median gives a hint of skew, but the name comes from the tail.","Incorrect — kurtosis describes tail weight on both sides, not the direction of asymmetry.",""],bookRef:"Book pp. 257–261"},{id:"sv-2-943",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"In a **right-skewed** distribution, where does the mean usually lie compared with the median?",options:["Below the median, pulled towards the peak","Exactly on the median","Exactly on the mode","Above the median, pulled towards the long tail"],answer:3,hint:"The mean is the balance point, so extreme values drag it towards the tail.",steps:[{title:"Key idea",body:"The mean uses every value, so the long tail of high values pulls it up."},{title:"Apply to the stem",body:"Right skew → mean > median; left skew → mean < median."}],final:"Right skew → mean above median → answer **D**",whyWrong:["Incorrect — the mean falls below the median in a left-skewed distribution.","Incorrect — mean and median coincide only when the data are symmetric.","Incorrect — the mode stays near the peak; the mean is dragged away by the tail.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-944",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"In which units is the **variance** of call-handling times recorded in minutes expressed?",options:["Minutes","Square root of minutes","A percentage of the mean","Minutes squared"],answer:3,hint:"Variance averages squared deviations.",steps:[{title:"Key idea",body:"Variance = average **squared** deviation from the mean, so its units are squared."},{title:"Eliminate look-alikes",body:"The standard deviation takes the root and returns to the original units."}],final:"Variance is in minutes² → answer **D**",whyWrong:["Incorrect — minutes are the units of the standard deviation, the square root of the variance.","Incorrect — no common spread statistic is in root units.","Incorrect — a percentage of the mean is the coefficient of variation.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-945",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"When should a variance be calculated with the divisor **N** rather than n − 1?",options:["When the sample contains more than 30 values","When the data are strongly skewed","When the data come from a destructive test","When the data contain every member of the population of interest"],answer:3,hint:"Population formula divides by N; sample formula divides by n − 1.",steps:[{title:"Key idea",body:"The book gives two formulas: σ uses **N** (whole population), s uses **n − 1** (sample)."},{title:"Apply to the stem",body:"Only when the data are the complete population is N used."}],final:"Whole population → divide by N → answer **D**",whyWrong:["Incorrect — sample size does not change the rule; sample data always use n − 1.","Incorrect — skewness affects which spread measure to report, not the divisor.","Incorrect — destructive testing matters for MSA design, not the variance formula.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-946",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"What is the main weakness of the **range** as a measure of variation for larger data sets?",options:["It is expressed in squared units","It uses only the two most extreme values and ignores the rest","It cannot be calculated for skewed data","It requires the data to be normally distributed"],answer:1,hint:"Range = maximum − minimum.",steps:[{title:"Key idea",body:"Range = largest − smallest, so it depends on just two values."},{title:"Apply to the stem",body:"As data grow, it ignores more information and one extreme value changes it completely; the SD becomes better."}],final:"Range uses only two values → answer **B**",whyWrong:["Incorrect — squared units belong to the variance, not the range.","","Incorrect — the range can be calculated for any data; skew does not prevent it.","Incorrect — the range makes no distribution assumption."],bookRef:"Book pp. 147–151"},{id:"sv-2-947",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"According to the book, for which sample size is the range **fully efficient** as a measure of spread?",options:["2","10","30","100"],answer:0,hint:"With only two values, max − min uses all the data.",steps:[{title:"Key idea",body:"Book p. 150: the range is fully efficient for a sample of **2**."},{title:"Apply to the stem",body:"As the sample grows, the standard deviation becomes the better measure."}],final:"Range fully efficient at n = 2 → answer **A**",whyWrong:["","Incorrect — at 10 values the range already ignores eight values; the SD becomes more efficient.","Incorrect — at 30 values the standard deviation is clearly the better measure.","Incorrect — at 100 values the range wastes almost all of the information."],bookRef:"Book pp. 147–151"},{id:"sv-2-948",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What does the **interquartile range (IQR)** describe?",options:["The spread between the smallest and largest value","The spread of the middle 50% of the data","The typical distance of the values from the mean","The spread of the middle 68% of the data"],answer:1,hint:"IQR = Q3 − Q1.",steps:[{title:"Key idea",body:"Q1 is the 25th percentile and Q3 the 75th, so Q3 − Q1 spans the middle **50%**."},{title:"Eliminate look-alikes",body:"Range = all data; SD = typical distance; 68% belongs to the empirical rule."}],final:"IQR = middle 50% → answer **B**",whyWrong:["Incorrect — that is the range.","","Incorrect — that is the standard deviation.","Incorrect — 68% is the empirical-rule share within ±1σ of a normal curve, not the IQR."],bookRef:"Book pp. 147–151"},{id:"sv-2-949",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"How does the book describe the role of the **standard deviation**?",options:["As the middle value of the sorted data","As the difference between the third and first quartiles","As the unit of measure for distances from the mean","As the average squared deviation from the mean"],answer:2,hint:"Distances such as 'two sigma from the mean' are counted in SDs.",steps:[{title:"Key idea",body:"Book p. 151: the SD is a 'typical distance' from the mean and the **unit of measure** for distances from it."},{title:"Apply to the stem",body:"This is why Z-scores and the empirical rule count in standard deviations."}],final:"SD = unit of distance from the mean → answer **C**",whyWrong:["Incorrect — the middle value is the median.","Incorrect — Q3 − Q1 is the interquartile range.","","Incorrect — the average squared deviation is the variance; the SD is its square root."],bookRef:"Book pp. 147–151"},{id:"sv-2-950",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"What does **SE Mean** in Minitab's descriptive statistics measure?",options:["How far a typical individual value lies from the mean","How far the mean lies from the median","How many values are missing from the column","How precisely the sample mean estimates the population mean"],answer:3,hint:"SE Mean = StDev divided by the square root of n.",steps:[{title:"Key idea",body:"The standard error is the standard deviation of the **sample mean**, not of the individual data."},{title:"Eliminate look-alikes",body:"StDev = spread of values; N* = missing values; mean vs median = skew clue."}],final:"SE Mean = precision of the mean → answer **D**",whyWrong:["Incorrect — that is the standard deviation (StDev) of the individual values.","Incorrect — the mean–median gap signals skewness; it is not the SE Mean.","Incorrect — missing values are counted in N*.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-951",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"If the standard deviation stays the same, what happens to the **SE Mean** as the sample size increases?",options:["It increases","It decreases","It stays the same","It becomes equal to the variance"],answer:1,hint:"SE Mean = s divided by √n.",steps:[{title:"Key idea",body:"The square root of n is in the denominator."},{title:"Apply to the stem",body:"More data → larger denominator → smaller SE Mean → a more precise estimate of the mean."}],final:"Larger n → smaller SE Mean → answer **B**",whyWrong:["Incorrect — dividing by a larger square root of n makes the standard error smaller, not larger.","","Incorrect — the standard error depends on n as well as on the SD.","Incorrect — the variance is the squared SD; the standard error never becomes the variance."],bookRef:"Book pp. 147–151"},{id:"sv-2-952",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What is the **coefficient of variation (CoefVar)** used for?",options:["Combining the variation of independent process steps","Measuring the spread of the middle half of the data","Comparing variation between processes with different means or units","Measuring how precisely the mean has been estimated"],answer:2,hint:"CoefVar = StDev as a percentage of the mean.",steps:[{title:"Key idea",body:"Expressing the SD as a % of the mean removes the units."},{title:"Apply to the stem",body:"So processes measured in seconds and in days can be compared for relative variation."}],final:"CV compares relative variation → answer **C**",whyWrong:["Incorrect — combining independent sources is done by adding variances.","Incorrect — the middle half is described by the interquartile range.","","Incorrect — precision of the mean is the SE Mean."],bookRef:"Book pp. 147–151"},{id:"sv-2-953",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What does **Q1** in a Minitab descriptive-statistics output represent?",options:["The value below which about 50% of the data fall","The value below which about 75% of the data fall","The smallest value in the data set","The value below which about 25% of the data fall"],answer:3,hint:"Quartiles cut the sorted data into four equal parts.",steps:[{title:"Key idea",body:"Q1 = 25th percentile, median = 50th, Q3 = 75th."},{title:"Eliminate look-alikes",body:"Minimum and Maximum are the extremes, shown separately."}],final:"Q1 = 25th percentile → answer **D**",whyWrong:["Incorrect — the 50th percentile is the median.","Incorrect — the 75th percentile is Q3.","Incorrect — the smallest value is the Minimum.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-954",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Which Minitab menu path produces the mean, standard deviation, quartiles and other summary statistics of a column?",options:["Stat > Basic Statistics > Normality Test","Stat > Quality Tools > Capability Analysis","Graph > Histogram","Stat > Basic Statistics > Display Descriptive Statistics"],answer:3,hint:"Book p. 147 names the menu used for 'Basic Statistics on Y'.",steps:[{title:"Key idea",body:"The book's output (N, Mean, SE Mean, StDev, Q1, Median, Q3…) comes from **Display Descriptive Statistics**."},{title:"Eliminate look-alikes",body:"The other paths answer normality, capability and shape questions."}],final:"Menu = Display Descriptive Statistics → answer **D**",whyWrong:["Incorrect — the Normality Test gives the Anderson-Darling result and a probability plot.","Incorrect — Capability Analysis compares the process with specification limits.","Incorrect — a histogram shows the shape but does not tabulate the statistics.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-955",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"Which combination of Minitab statistics describes a **symmetric** distribution that produces **more extreme values** than a normal curve?",options:["Skewness near 0 and clearly positive kurtosis","Skewness near 0 and clearly negative kurtosis","Clearly positive skewness and kurtosis near 0","Clearly negative skewness and kurtosis near 0"],answer:0,hint:"Skewness = symmetry; kurtosis = tail weight.",steps:[{title:"Key idea",body:"Symmetric → skewness ≈ 0."},{title:"Apply to the stem",body:"More extreme values in both tails → heavy tails → kurtosis **positive**."},{title:"Eliminate look-alikes",body:"The skewed options break symmetry; negative kurtosis gives fewer extremes."}],final:"Skew ≈ 0, kurtosis > 0 → answer **A**",whyWrong:["","Incorrect — negative kurtosis means lighter tails, so fewer extreme values than normal.","Incorrect — positive skewness means a long right tail, so the shape is not symmetric.","Incorrect — negative skewness means a long left tail, so the shape is not symmetric."],bookRef:"Book pp. 257–261"},{id:"sv-2-956",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"How is the rule 'variances add' applied in measurement system analysis?",options:["By adding the part-to-part and measurement standard deviations to give the total standard deviation","By adding the part-to-part variance and the measurement variance to give the total observed variance","By averaging the ranges of each appraiser to give the total variation","By dividing the measurement variance by the tolerance to give the total variance"],answer:1,hint:"Observed variation = part variation + measurement variation, in variance terms.",steps:[{title:"Key idea",body:"Independent sources combine through their **variances**."},{title:"Apply to the stem",body:"Gage R&R splits total observed variance into part-to-part and measurement components that add up."}],final:"Variance components add → answer **B**",whyWrong:["Incorrect — standard deviations cannot be added; only variances combine this way.","","Incorrect — average ranges are used inside the R&R calculation, but they are not added to make total variation.","Incorrect — comparing with the tolerance gives %Tolerance, not the total variance."],bookRef:"Book pp. 147–151"},{id:"sv-2-957",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about **skewness** is CORRECT?",options:["Skewness is named after the side on which the peak lies","A skewness close to zero proves that the data are normal","In a left-skewed distribution the mean is usually below the median","Cycle times that cannot fall below zero are usually left-skewed"],answer:2,hint:"The long tail drags the mean towards it.",steps:[{title:"Key idea",body:"Left (negative) skew = long tail of low values, which pulls the mean **below** the median."},{title:"Eliminate look-alikes",body:"Naming follows the tail; symmetry ≠ normality; times bounded at zero skew right."}],final:"Left skew → mean below median → answer **C**",whyWrong:["Incorrect — skewness is named after the side of the long tail.","Incorrect — symmetric data can still be non-normal, for example flat or bimodal; skewness alone proves nothing.","","Incorrect — times bounded at zero usually have a long right tail (right skew)."],bookRef:"Book pp. 257–261"},{id:"sv-2-958",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about the **variance** is CORRECT?",options:["It is the square root of the standard deviation","For a sample, the sum of squared deviations is divided by N","It is not affected by extreme values","It is expressed in squared units, which makes it hard to interpret directly"],answer:3,hint:"Variance = average squared deviation.",steps:[{title:"Key idea",body:"Squaring the deviations gives squared units (min², mm²)."},{title:"Apply to the stem",body:"That is why the SD, in data units, is reported for interpretation."}],final:"Variance in squared units → answer **D**",whyWrong:["Incorrect — it is the other way round: the SD is the square root of the variance.","Incorrect — sample variance divides by n − 1; N is used for a population.","Incorrect — squaring deviations makes the variance very sensitive to extreme values.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-959",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about the **interquartile range** is CORRECT?",options:["It resists extreme values because it ignores the lowest and highest 25% of the data","It is calculated as the maximum minus the minimum","It covers the middle 68% of the data","It is the book's preferred spread measure for symmetric data"],answer:0,hint:"IQR = Q3 − Q1.",steps:[{title:"Key idea",body:"Only the middle half of the sorted data is used."},{title:"Apply to the stem",body:"So a few extreme values in either tail barely move it."}],final:"IQR resists extremes → answer **A**",whyWrong:["","Incorrect — maximum minus minimum is the range.","Incorrect — the IQR covers the middle 50%; 68% is the ±1σ share of a normal curve.","Incorrect — the book prefers the standard deviation for symmetric data and the IQR for skewed data."],bookRef:"Book pp. 147–151"},{id:"sv-2-960",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about **measures of location** is CORRECT?",options:["The trimmed mean is more affected by extreme values than the mean","The median is the 50th percentile of the sorted data","A data set can have only one mode","In a right-skewed data set the mean equals the median"],answer:1,hint:"Mean, median, mode and trimmed mean each locate the centre differently.",steps:[{title:"Key idea",body:"Median = middle value = 50th percentile (book p. 148)."},{title:"Eliminate look-alikes",body:"Trimmed mean resists extremes; multiple modes are possible; skew separates mean and median."}],final:"Median = 50th percentile → answer **B**",whyWrong:["Incorrect — trimming removes the extremes, so the trimmed mean is less affected than the mean.","","Incorrect — a data set can have two or more modes, for example a bimodal one.","Incorrect — in right-skewed data the mean is pulled above the median."],bookRef:"Book pp. 147–151"},{id:"sv-2-961",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about using the **range** to describe variation is CORRECT?",options:["It is resistant to a single extreme value","It uses every value in the data set","It works well for very small subgroups because it is efficient when n is small","It is expressed in squared units"],answer:2,hint:"Range = max − min; efficient at n = 2.",steps:[{title:"Key idea",body:"The book says the range is fully efficient for a sample of 2 and loses out to the SD as n grows."},{title:"Apply to the stem",body:"That is why it suits small subgroups, such as the R chart's subgroups of 2–5."}],final:"Range suits small subgroups → answer **C**",whyWrong:["Incorrect — one extreme value changes the range completely.","Incorrect — it uses only the largest and smallest values.","","Incorrect — the range is in data units; squared units belong to the variance."],bookRef:"Book pp. 147–151"},{id:"sv-2-962",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"A Minitab output shows a **mean much larger than the median**. Which statement is CORRECT?",options:["A few small values are pulling the mean upwards","The data are skewed to the left","The data must be symmetric","A few large values are pulling the mean upwards"],answer:3,hint:"Book p. 147: compare the measures within a family.",steps:[{title:"Key idea",body:"The median ignores extreme values; the mean does not."},{title:"Apply to the stem",body:"Mean ≫ median → a tail of large values → right skew."}],final:"Mean ≫ median → large values pull it up → answer **D**",whyWrong:["Incorrect — small values pull the mean down, not up.","Incorrect — left skew puts the mean below the median.","Incorrect — in symmetric data the mean and median are close.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-963",phase:2,topic:"2.2.2",qtype:"statements",difficulty:2,stem:`Consider these statements about the **shape** of a distribution:

1. Positive skewness means a long tail towards the high values.
2. Negative kurtosis means lighter tails than a normal distribution.
3. A skewness of zero guarantees that the data are normal.
4. Kurtosis describes where the centre of the data lies.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Skewness = asymmetry (named by the tail); kurtosis = tail weight.",steps:[{title:"Key idea",body:"1 is true (right tail = positive skew); 2 is true (negative kurtosis = platykurtic)."},{title:"Eliminate look-alikes",body:"3 confuses symmetry with normality; 4 confuses kurtosis with location."}],final:"1 and 2 are true → answer **A**",whyWrong:["","Incorrect — statement 3 is false: symmetric data can still be flat, peaked or bimodal.","Incorrect — both are false: zero skew does not prove normality, and kurtosis is about tails, not location.","Incorrect — statement 4 is false: the centre is described by mean, median or mode."],bookRef:"Book pp. 257–261"},{id:"sv-2-964",phase:2,topic:"2.2.2",qtype:"statements",difficulty:2,stem:`Consider these statements about **variance and standard deviation**:

1. The standard deviation is the square of the variance.
2. The sample variance divides the sum of squared deviations by n − 1.
3. Variances of independent sources of variation can be added.
4. The standard deviation is expressed in squared units.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Variance = squared units, n − 1 for samples, additive; SD = its root.",steps:[{title:"Key idea",body:"2 and 3 are book facts (pp. 150–151)."},{title:"Eliminate look-alikes",body:"1 reverses the root/square relation; 4 gives the SD the variance's units."}],final:"2 and 3 are true → answer **B**",whyWrong:["Incorrect — statement 1 is false: the SD is the square root of the variance.","","Incorrect — statement 4 is false: the SD is in the same units as the data.","Incorrect — both are false: the SD is the root of the variance and is in data units."],bookRef:"Book pp. 147–151"},{id:"sv-2-965",phase:2,topic:"2.2.2",qtype:"statements",difficulty:2,stem:`Consider these statements about the **range and the interquartile range (IQR)**:

1. The IQR is the largest value minus the smallest value.
2. The range is resistant to extreme values.
3. The IQR covers the middle 50% of the data.
4. The range uses only the largest and smallest values.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Range = max − min; IQR = Q3 − Q1.",steps:[{title:"Key idea",body:"3 and 4 are true."},{title:"Eliminate look-alikes",body:"1 swaps the definitions; 2 gives the range the IQR's resistance."}],final:"3 and 4 are true → answer **C**",whyWrong:["Incorrect — both are false: max − min is the range, and the range is very sensitive to extremes.","Incorrect — statement 2 is false: one extreme value changes the range completely.","","Incorrect — statement 1 is false: max − min defines the range, not the IQR."],bookRef:"Book pp. 147–151"},{id:"sv-2-966",phase:2,topic:"2.2.2",qtype:"statements",difficulty:2,stem:`Consider these statements about fields in Minitab's **Display Descriptive Statistics** output:

1. N* is the number of missing values in the column.
2. SE Mean describes the spread of the individual observations.
3. Q1 is the median of the whole data set.
4. CoefVar expresses the standard deviation as a percentage of the mean.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Know what each column of the output means.",steps:[{title:"Key idea",body:"1 (N* = missing) and 4 (CoefVar = SD as % of mean) are true."},{title:"Eliminate look-alikes",body:"2 swaps SE Mean with StDev; 3 swaps Q1 with the median."}],final:"1 and 4 are true → answer **D**",whyWrong:["Incorrect — statement 2 is false: the spread of individual values is StDev; SE Mean is the precision of the mean.","Incorrect — both are false: SE Mean is not individual spread, and Q1 is the 25th percentile.","Incorrect — statement 3 is false: Q1 is the 25th percentile; the median is the 50th.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-967",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

The [?] is the difference between the third quartile and the first quartile.`,options:["interquartile range","range","standard error","variance"],answer:0,hint:"Quartile difference → quartile range.",steps:[{title:"Key idea",body:"IQR = Q3 − Q1 (book p. 150)."},{title:"Eliminate look-alikes",body:"Range uses the extremes; SE and variance are based on deviations from the mean."}],final:"Q3 − Q1 = interquartile range → answer **A**",whyWrong:["","Incorrect — the range is the maximum minus the minimum.","Incorrect — the standard error is the SD divided by the square root of n.","Incorrect — the variance is the average squared deviation from the mean."],bookRef:"Book pp. 147–151"},{id:"sv-2-968",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

In a distribution with [?] skewness, the long tail lies on the left and the mean is usually below the median.`,options:["negative","positive","symmetric","zero"],answer:0,hint:"Left tail = negative.",steps:[{title:"Key idea",body:"A long tail of low values = left skew = **negative** skewness."},{title:"Apply to the stem",body:"The tail drags the mean down below the median."}],final:"Left tail = negative skewness → answer **A**",whyWrong:["","Incorrect — positive skewness has the long tail on the right and the mean above the median.","Incorrect — symmetric data have no long tail, so the mean and median are close.","Incorrect — zero skewness means a symmetric shape, with no long tail."],bookRef:"Book pp. 257–261"},{id:"sv-2-969",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word(s) in the following sentence.

To obtain the sample variance, the sum of squared deviations from the sample mean is divided by [?].`,options:["n − 1","n","n + 1","√n"],answer:0,hint:"Sample formulas lose one degree of freedom.",steps:[{title:"Key idea",body:"Book p. 151: s² divides by **n − 1**; σ² divides by N."},{title:"Eliminate look-alikes",body:"√n belongs to SE Mean."}],final:"Sample variance divides by n − 1 → answer **A**",whyWrong:["","Incorrect — dividing by n is the population formula (written N), used only for a whole population.","Incorrect — n + 1 is not used in any standard variance formula.","Incorrect — √n appears in the standard error of the mean, not in the variance."],bookRef:"Book pp. 147–151"},{id:"sv-2-970",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:2,stem:"Which is NOT a property of the **variance**?",options:["It is resistant to extreme values","It is expressed in squared units","It can be added across independent sources of variation","It equals the square of the standard deviation"],answer:0,hint:"Squaring the deviations magnifies large ones.",steps:[{title:"Key idea",body:"Squared units, additivity and SD² are all true of the variance."},{title:"Apply to the stem",body:"Squaring gives extreme values even more weight, so the variance is **not** resistant."}],final:"Variance is not resistant to extremes → answer **A**",whyWrong:["","Incorrect — this is a property: squaring the deviations gives squared units.","Incorrect — this is a property: variances of independent sources add.","Incorrect — this is a property: the SD is the square root of the variance."],bookRef:"Book pp. 147–151"},{id:"sv-2-971",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:2,stem:"Which of these does NOT indicate **positive (right) skew**?",options:["The mean is larger than the median","The median is larger than the mean","There is a long tail towards the high values","Minitab reports a skewness of +1.6"],answer:1,hint:"Right skew drags the mean up past the median.",steps:[{title:"Key idea",body:"Right skew: long right tail, positive coefficient, mean > median."},{title:"Apply to the stem",body:"Median > mean points the other way — **left** skew."}],final:"Median > mean signals left skew → answer **B**",whyWrong:["Incorrect — mean above median is a sign of right skew.","","Incorrect — a long tail of high values defines right skew.","Incorrect — a positive skewness coefficient indicates right skew."],bookRef:"Book pp. 257–261"},{id:"sv-2-972",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:3,stem:"The interquartile range is useful for all of the following EXCEPT:",options:["Summarising the spread of skewed data","Drawing the box of a box plot","Combining the variation of independent process steps","Describing spread when a few extreme values are present"],answer:2,hint:"Only one spread statistic adds across independent sources.",steps:[{title:"Key idea",body:"The IQR suits skewed data, outliers and box plots."},{title:"Apply to the stem",body:"Combining independent sources needs **variances**, which add; IQRs do not."}],final:"Combining sources needs variances → answer **C**",whyWrong:["Incorrect — the book recommends the IQR for skewed data.","Incorrect — the box of a box plot runs from Q1 to Q3, which is the IQR.","","Incorrect — the IQR ignores the extreme quarters, so it suits data with outliers."],bookRef:"Book pp. 147–151"},{id:"sv-2-973",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:2,stem:"Two moulding lines make caps with the same mean and almost the same standard deviation. However, line B produces noticeably more caps far from the mean, while most of its caps sit very close to the centre. Which statistic would capture this difference?",options:["Skewness","Median","Coefficient of variation","Kurtosis"],answer:3,hint:"More values in the peak and the tails, same SD.",steps:[{title:"Key idea",body:"A sharper peak with heavier tails is a kurtosis difference."},{title:"Apply to the stem",body:"Line B would show clearly **positive** kurtosis (leptokurtic)."}],final:"Peak and tails → kurtosis → answer **D**",whyWrong:["Incorrect — skewness measures asymmetry; the stem describes both tails, not one side.","Incorrect — the median is a location measure; the centres are the same.","Incorrect — with the same mean and SD the CVs would be almost the same.",""],bookRef:"Book pp. 257–261"},{id:"sv-2-974",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:1,stem:"Most billing-dispute amounts in a month are small, but a handful of corporate disputes are very large, giving a long tail of high values. How should the shape of this distribution be described?",options:["Positively skewed","Negatively skewed","Symmetric with negative kurtosis","Bimodal"],answer:0,hint:"Name the skew after the tail.",steps:[{title:"Key idea",body:"A long tail towards high values = right skew = **positive** skewness."},{title:"Apply to the stem",body:"The mean will sit above the median."}],final:"Long high tail = positive skew → answer **A**",whyWrong:["","Incorrect — negative skew would need a long tail of low values.","Incorrect — a long one-sided tail is not symmetric; negative kurtosis means flat with light tails.","Incorrect — bimodal needs two peaks; here there is one peak and a long tail."],bookRef:"Book pp. 257–261"},{id:"sv-2-975",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:3,stem:"Agent quality scores are capped at 100. Most agents score between 90 and 100, but a few new agents score below 50. The team needs one figure for the typical score. Which measure should it report?",options:["The mean, because it uses every score","The median, because the long tail of low scores pulls the mean down","The mode, because it is always the most representative value","The range, because it shows the full spread of scores"],answer:1,hint:"Skewed data → resistant measure of centre.",steps:[{title:"Key idea",body:"A long tail of low values = left skew, which pulls the mean below the bulk of the data."},{title:"Apply to the stem",body:"The **median** is not affected by the extreme values."}],final:"Left-skewed → report the median → answer **B**",whyWrong:["Incorrect — using every score is the problem: the few low scores drag the mean down.","","Incorrect — the mode can be unstable and is not always representative.","Incorrect — the range is a measure of spread, not of the typical value."],bookRef:"Book pp. 147–151"},{id:"sv-2-976",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:3,stem:"Every hour an operator weighs **four** consecutive bottles and must record the spread of each subgroup by hand on the line. Which measure of variation is the most practical choice?",options:["The variance","The interquartile range","The range","The coefficient of variation"],answer:2,hint:"Which measure is efficient at very small n?",steps:[{title:"Key idea",body:"The range is fully efficient at n = 2 and still good for very small subgroups."},{title:"Apply to the stem",body:"It is quick to compute by hand: largest − smallest."}],final:"Small subgroups → range → answer **C**",whyWrong:["Incorrect — the variance needs squared deviations and gives squared units; too slow by hand.","Incorrect — quartiles of four values are unstable and add nothing over the range.","","Incorrect — the CV compares relative variation across processes, not within one small subgroup."],bookRef:"Book pp. 147–151"},{id:"sv-2-977",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:2,stem:"A manager wants to know which is relatively more consistent: chat response time (mean in **seconds**) or engineer dispatch time (mean in **hours**). Which statistic allows a fair comparison?",options:["Standard deviation","Variance","Range","Coefficient of variation"],answer:3,hint:"Remove the units by expressing spread relative to the mean.",steps:[{title:"Key idea",body:"CoefVar = SD as a % of the mean, so it has no units."},{title:"Apply to the stem",body:"The process with the smaller CV is relatively more consistent."}],final:"Different units → CV → answer **D**",whyWrong:["Incorrect — SDs in seconds and in hours cannot be compared directly.","Incorrect — variances in s² and h² are even harder to compare.","Incorrect — ranges keep the original units, so they cannot be compared across scales.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-978",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:3,stem:"A team has the delivery times of **all 48** enterprise orders delivered this year and wants the variance of this complete set. No inference to other orders is intended. Which divisor should be used?",options:["N, the number of orders","n − 1","n − 2","The square root of N"],answer:0,hint:"Population or sample?",steps:[{title:"Key idea",body:"Book p. 151: population variance divides by **N**; sample variance by n − 1."},{title:"Apply to the stem",body:"All 48 orders are the whole population of interest, so divide by N."}],final:"Whole population → N → answer **A**",whyWrong:["","Incorrect — n − 1 is for sample data used to estimate a wider population.","Incorrect — n − 2 is not used for a single variance.","Incorrect — a square root of n appears in the standard error, not the variance."],bookRef:"Book pp. 147–151",trap:"On most exam items the data are a sample, so n − 1 is the default — read the stem."},{id:"sv-2-979",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:2,stem:"A machining team measured **50 shafts** and wants to state how precisely their sample mean estimates the true mean diameter of all shafts. Which statistic from the Minitab output should they use?",options:["StDev","SE Mean","Interquartile range","Kurtosis"],answer:1,hint:"Precision of the mean, not spread of the parts.",steps:[{title:"Key idea",body:"SE Mean = StDev ÷ √n: the standard deviation of the sample mean."},{title:"Apply to the stem",body:"A small SE Mean means the sample mean is a precise estimate."}],final:"Precision of the mean = SE Mean → answer **B**",whyWrong:["Incorrect — StDev describes the spread of individual shafts, not the precision of the mean.","","Incorrect — the IQR describes the spread of the middle 50% of shafts.","Incorrect — kurtosis describes tail shape."],bookRef:"Book pp. 147–151"},{id:"sv-2-980",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:2,stem:"A Green Belt reports the baseline of strongly right-skewed refund times to management as the **mean and standard deviation**. Was this an appropriate action?",options:["Yes, because the mean and standard deviation use every data point","Yes, because the standard deviation is in the same units as the data","No, because skewed data are better summarised by the median and the IQR","No, because skewed data should be summarised by the mode and the variance"],answer:2,hint:"Book p. 150: match the summary to the shape.",steps:[{title:"Key idea",body:"Symmetric → mean + SD; skewed → median + IQR (or range)."},{title:"Apply to the stem",body:"Strong right skew inflates the mean and SD, so the action was not appropriate."}],final:"Skewed → median + IQR → answer **C**",whyWrong:["Incorrect — using every point is the weakness here: the long tail distorts both statistics.","Incorrect — matching units does not fix the distortion caused by the skew.","","Incorrect — the mode is unstable and the variance is in squared units; neither is the book's choice."],bookRef:"Book pp. 147–151"},{id:"sv-2-981",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:3,stem:"Minitab reports **skewness 0.1** and **kurtosis +5.2** for 300 latency readings. What should the Green Belt do FIRST?",options:["Recalculate the standard deviation using N instead of n − 1","Report that the data are strongly left-skewed","Plot the data and examine the extreme readings in the tails","Report the mean only, because the data are symmetric"],answer:2,hint:"Heavy tails = more extreme values than normal.",steps:[{title:"Key idea",body:"High positive kurtosis → leptokurtic → many extreme values."},{title:"Apply to the stem",body:"Look at a histogram or box plot and investigate those extreme readings before summarising."}],final:"Investigate the heavy tails first → answer **C**",whyWrong:["Incorrect — the divisor has nothing to do with a high kurtosis.","Incorrect — skewness 0.1 means roughly symmetric, not left-skewed.","","Incorrect — symmetric does not mean normal; heavy tails need to be understood first."],bookRef:"Book pp. 257–261"},{id:"sv-2-982",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:3,stem:"A Green Belt measured call-handling times on a single morning and used that sample's standard deviation as the **long-term** baseline for the project. Was this an appropriate action?",options:["Yes, because one morning gives a random sample","Yes, because the standard deviation does not depend on when data are collected","No, because a short-period sample may miss variation that builds up over time","No, because the variance, not the standard deviation, should be reported"],answer:2,hint:"Book p. 151: short-term vs long-term variation.",steps:[{title:"Key idea",body:"A sample from a short period can understate the true long-term variation."},{title:"Apply to the stem",body:"Collect data across shifts, days and weeks before setting a baseline."}],final:"Short sample understates long-term SD → answer **C**",whyWrong:["Incorrect — one morning cannot show shift, day or week effects, however randomly the calls are picked.","Incorrect — the SD of a short period is usually smaller than the long-term SD.","","Incorrect — reporting the variance instead would not fix the short time window."],bookRef:"Book pp. 147–151"},{id:"sv-2-983",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:3,stem:"In a report to executives, a Green Belt states: 'Repair times vary from the average by about **36 minutes**', quoting the **variance** of 36 min² from Minitab. Was this an appropriate action?",options:["Yes, because the variance is the average deviation from the mean","Yes, because variance and standard deviation are interchangeable","No, because the interquartile range must always be reported instead","No, because the variance is in squared units; the standard deviation should be quoted"],answer:3,hint:"Variance = squared units.",steps:[{title:"Key idea",body:"A variance of 36 min² is not 36 minutes."},{title:"Apply to the stem",body:"The typical distance from the mean is the standard deviation, in minutes."}],final:"Quote the SD, not the variance → answer **D**",whyWrong:["Incorrect — the variance is the average squared deviation, not the average deviation.","Incorrect — the SD is the square root of the variance; the two numbers differ.","Incorrect — the IQR is for skewed data; the error is the units.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-984",phase:2,topic:"2.2.2",qtype:"output",difficulty:2,stem:`Minitab output for 200 bottle fill volumes:

\`\`\`
Descriptive Statistics: FillVol (ml)

Variable    N    Mean  SE Mean  StDev  Minimum      Q1  Median      Q3  Maximum  Skewness  Kurtosis
FillVol   200  500.12    0.130   1.84   496.90  498.60  500.10  501.70   503.30      0.04     -1.12
\`\`\`

Which statement BEST describes the shape of the data?`,options:["Roughly symmetric, with a sharper peak and heavier tails than a normal curve","Left-skewed, with a long tail of low fill volumes","Right-skewed, with a long tail of high fill volumes","Roughly symmetric, with a flatter peak and lighter tails than a normal curve"],answer:3,hint:"Skewness → symmetry; kurtosis → tails and peak.",steps:[{title:"Key idea",body:"Skewness 0.04 and mean ≈ median → roughly symmetric."},{title:"Apply to the stem",body:"Kurtosis −1.12 → negative → platykurtic: flat top, light tails."}],final:"Symmetric and platykurtic → answer **D**",whyWrong:["Incorrect — that would need positive kurtosis; here it is −1.12.","Incorrect — skewness is 0.04 and mean ≈ median, so there is no long left tail.","Incorrect — skewness is 0.04 and mean ≈ median, so there is no long right tail.",""],bookRef:"Book pp. 257–261"},{id:"sv-2-985",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Minitab output for shaft diameters from two lines:

\`\`\`
Descriptive Statistics: Diameter (mm)

Variable  Line    N    Mean   StDev  Skewness  Kurtosis
Diameter  A     150  25.002   0.011      0.03      0.08
          B     150  25.001   0.011     -0.05      3.92
\`\`\`

Which conclusion is CORRECT?`,options:["Line B is likely to produce more extreme diameters than line A, although both have the same SD","Line B is strongly left-skewed","Line A has more extreme diameters because its kurtosis is closer to zero","The two lines have identical distributions because mean and SD match"],answer:0,hint:"Same centre and SD do not mean the same shape.",steps:[{title:"Key idea",body:"Line B kurtosis 3.92 → strongly leptokurtic → heavy tails."},{title:"Apply to the stem",body:"Heavy tails mean more values far from the mean than line A (kurtosis 0.08)."},{title:"Eliminate look-alikes",body:"Skewness is ≈ 0 for both, so neither is skewed."}],final:"Line B has heavy tails → answer **A**",whyWrong:["","Incorrect — skewness of −0.05 is essentially symmetric.","Incorrect — kurtosis near zero means normal-like tails, so fewer extremes than line B.","Incorrect — mean and SD match, but kurtosis shows a different tail shape."],bookRef:"Book pp. 257–261"},{id:"sv-2-986",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Minitab output for the first-contact resolution score (%) of 80 agents:

\`\`\`
Descriptive Statistics: FCR (%)

Variable   N   Mean  SE Mean  StDev  Minimum     Q1  Median     Q3  Maximum  Skewness  Kurtosis
FCR       80  82.10     1.30  11.60    41.00  77.50   86.00  90.50    98.50     -1.45      1.88
\`\`\`

Which statement is CORRECT?`,options:["The data are right-skewed, so the mean overstates a typical agent","The data are left-skewed, so the median is a better summary of a typical agent than the mean","The data are symmetric, so mean and median are interchangeable","The negative skewness means most agents score below the mean"],answer:1,hint:"Negative skewness, mean below median.",steps:[{title:"Key idea",body:"Skewness −1.45 and mean (82.1) < median (86.0) → long tail of low scores."},{title:"Apply to the stem",body:"The few low scorers drag the mean down, so the median is the better typical value."}],final:"Left-skewed → median → answer **B**",whyWrong:["Incorrect — skewness is negative and mean < median, so the tail is on the left.","","Incorrect — skewness of −1.45 and a 4-point gap between mean and median show clear asymmetry.","Incorrect — the median is above the mean, so more than half of the agents score above the mean."],bookRef:"Book pp. 257–261"},{id:"sv-2-987",phase:2,topic:"2.2.2",qtype:"output",difficulty:1,stem:`Minitab output for home-installation times:

\`\`\`
Descriptive Statistics: InstallTime (h)

Variable       N  N*   Mean  SE Mean  StDev  Median
InstallTime  186  14  3.420    0.098  1.340   3.150
\`\`\`

What does **N\\* = 14** indicate?`,options:["Fourteen values were identified as outliers and removed","Fourteen installations exceeded the specification limit","Fourteen rows in the column had no value and were excluded","Fourteen values were trimmed to calculate the trimmed mean"],answer:2,hint:"N = values used; N* = values missing.",steps:[{title:"Key idea",body:"N* counts the missing (blank) cells in the column."},{title:"Apply to the stem",body:"So 14 records had no installation time, and the statistics use the 186 that did."}],final:"N* = missing values → answer **C**",whyWrong:["Incorrect — Minitab does not remove outliers in descriptive statistics; N* counts blanks.","Incorrect — descriptive statistics know nothing about specification limits.","","Incorrect — trimming is reported as TrMean, not as N*."],bookRef:"Book pp. 147–151"},{id:"sv-2-988",phase:2,topic:"2.2.2",qtype:"output",difficulty:2,stem:`Minitab output for 400 call wait times:

\`\`\`
Descriptive Statistics: Wait (s)

Variable    N   Mean  SE Mean  StDev
Wait      400  46.20     1.10  22.00
\`\`\`

Which statement is CORRECT?`,options:["SE Mean describes the spread of individual waits; StDev describes the uncertainty in the estimated mean","Most individual wait times lie within about 1.10 s of the mean","SE Mean would increase if more calls were sampled","StDev describes the spread of individual waits; SE Mean describes the uncertainty in the estimated mean"],answer:3,hint:"StDev = individuals; SE Mean = the mean.",steps:[{title:"Key idea",body:"StDev (22.0 s) = typical distance of individual waits from the mean."},{title:"Apply to the stem",body:"SE Mean (1.10 s) = standard deviation of the sample mean — how precisely 46.2 s is known."}],final:"StDev vs SE Mean → answer **D**",whyWrong:["Incorrect — this swaps the two statistics.","Incorrect — individual waits spread by about the StDev (22 s), not by the SE Mean.","Incorrect — SE Mean = StDev ÷ √n, so more data make it smaller.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-989",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Minitab output for two processes:

\`\`\`
Descriptive Statistics

Variable          N    Mean  StDev  CoefVar
Handle (s)       60  240.00  19.70     8.21
Dispatch (min)   60   12.00   2.58    21.50
\`\`\`

Which conclusion is CORRECT?`,options:["Dispatch time has the greater variation relative to its mean","Handle time has the greater relative variation because its StDev is larger","The two processes cannot be compared because their units differ","Both processes have the same relative variation because N is equal"],answer:0,hint:"Compare CoefVar, not StDev, across units.",steps:[{title:"Key idea",body:"CoefVar expresses StDev as a % of the mean, with no units."},{title:"Apply to the stem",body:"Dispatch 21.50% > Handle 8.21%, so dispatch is relatively more variable."}],final:"Higher CV → dispatch more variable → answer **A**",whyWrong:["","Incorrect — the raw SDs are in different units; the CV shows handle time is relatively less variable.","Incorrect — the CV removes the units precisely so that such a comparison is possible.","Incorrect — equal sample sizes say nothing about relative variation."],bookRef:"Book pp. 147–151"},{id:"sv-2-990",phase:2,topic:"2.2.2",qtype:"output",difficulty:2,stem:`Minitab output for three Y measures:

\`\`\`
Descriptive Statistics

Variable        N   Mean  Median  Skewness
Setup (min)    60  50.10   50.00      0.03
Outage (min)   60  38.60   31.20      1.72
Survey (%)     60  71.40   76.90     -1.31
\`\`\`

Which statement is CORRECT?`,options:["Survey has a long tail of high values","Outage has a long tail of high values","Setup is strongly skewed to the right","Outage and Survey are skewed in the same direction"],answer:1,hint:"Sign of skewness and the mean–median gap give the tail side.",steps:[{title:"Key idea",body:"Outage: skewness +1.72, mean > median → right tail."},{title:"Eliminate look-alikes",body:"Survey: −1.31, mean < median → left tail; Setup ≈ 0 → symmetric."}],final:"Outage is right-skewed → answer **B**",whyWrong:["Incorrect — Survey's skewness is negative and its mean is below its median, so its tail is low.","","Incorrect — Setup's skewness is 0.03 with mean ≈ median, so it is symmetric.","Incorrect — Outage is positive (right) and Survey negative (left)."],bookRef:"Book pp. 257–261"},{id:"sv-2-991",phase:2,topic:"2.2.2",qtype:"true-false",difficulty:1,stem:"A distribution with a long tail to the **left** has positive skewness. True or False?",options:["True","False"],answer:1,hint:"Skew is named after the tail.",steps:[{title:"Key idea",body:"Long left tail = left skew = **negative** skewness."},{title:"Apply to the stem",body:"The statement reverses the sign."}],final:"Left tail = negative skew → answer **False**",whyWrong:["Incorrect — a long left tail gives negative skewness; positive skew has the long tail on the right.",""],bookRef:"Book pp. 257–261"},{id:"sv-2-992",phase:2,topic:"2.2.2",qtype:"true-false",difficulty:1,stem:"The variance of a data set is expressed in the **squared** units of the original measurements. True or False?",options:["True","False"],answer:0,hint:"Variance = average squared deviation.",steps:[{title:"Key idea",body:"Squaring the deviations squares the units (mm → mm²)."},{title:"Apply to the stem",body:"The statement is true."}],final:"Variance in squared units → answer **True**",whyWrong:["","Incorrect — the variance averages squared deviations, so its units are squared; the SD returns to data units."],bookRef:"Book pp. 147–151"},{id:"sv-2-993",phase:2,topic:"2.2.2",qtype:"sequence",difficulty:2,stem:`A Green Belt calculates a **sample standard deviation** by hand.

1. Divide the sum of squared deviations by n − 1
2. Calculate the sample mean
3. Take the square root
4. Subtract the mean from each value and square the results

What is the correct order?`,options:["4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3","2, 4, 3, 1"],answer:2,hint:"Mean → deviations² → divide by n − 1 → root.",steps:[{title:"Key idea",body:"The variance comes first: mean, squared deviations, divide by n − 1."},{title:"Apply to the stem",body:"The SD is the square root of that variance."}],final:"Order 2, 4, 1, 3 → answer **C**",whyWrong:["Incorrect — deviations cannot be taken before the mean is known.","Incorrect — the deviations must be squared and summed before dividing by n − 1.","","Incorrect — the square root comes last; rooting before dividing gives a wrong value."],bookRef:"Book pp. 147–151"},{id:"sv-2-994",phase:2,topic:"2.2.2",qtype:"sequence",difficulty:2,stem:`A Green Belt finds the **interquartile range** of 40 ticket times.

1. Subtract Q1 from Q3
2. Sort the data from smallest to largest
3. Split the sorted data at the median
4. Find the middle of each half to get Q1 and Q3

What is the correct order?`,options:["3, 2, 4, 1","2, 4, 3, 1","2, 3, 1, 4","2, 3, 4, 1"],answer:3,hint:"Quartiles need sorted data.",steps:[{title:"Key idea",body:"Sort first, then split at the median."},{title:"Apply to the stem",body:"The middle of the lower half is Q1, of the upper half Q3; IQR = Q3 − Q1."}],final:"Order 2, 3, 4, 1 → answer **D**",whyWrong:["Incorrect — the median cannot be found before the data are sorted.","Incorrect — the halves must exist before their middles (Q1, Q3) can be found.","Incorrect — Q1 and Q3 must be found before they can be subtracted.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-995",phase:2,topic:"2.2.2",qtype:"sequence",difficulty:2,stem:`A Green Belt calculates a **trimmed mean** of refund times and checks its effect.

1. Average the remaining values
2. Sort the values
3. Remove the stated percentage of values from each end
4. Compare the result with the mean and median

What is the correct order?`,options:["2, 3, 1, 4","3, 2, 1, 4","2, 1, 3, 4","2, 3, 4, 1"],answer:0,hint:"Sort → trim both ends → average.",steps:[{title:"Key idea",body:"Book p. 149: remove a set % of the smallest and largest values, then average the rest."},{title:"Apply to the stem",body:"Comparing with mean and median shows how much the extremes mattered."}],final:"Order 2, 3, 1, 4 → answer **A**",whyWrong:["","Incorrect — the extremes can only be identified after sorting.","Incorrect — averaging before trimming just gives the ordinary mean.","Incorrect — the trimmed mean must exist before it can be compared."],bookRef:"Book pp. 147–151"},{id:"sv-2-996",phase:2,topic:"2.2.2",qtype:"sequence",difficulty:3,stem:`A Green Belt summarises the baseline of a new Y in Measure.

1. Choose the summary pair: mean and SD, or median and IQR
2. Run Display Descriptive Statistics on the data
3. Report the baseline to the sponsor
4. Compare mean with median and check skewness and kurtosis

What is the correct order?`,options:["4, 2, 1, 3","2, 4, 1, 3","2, 1, 4, 3","1, 2, 4, 3"],answer:1,hint:"Statistics → shape → choose → report.",steps:[{title:"Key idea",body:"First get the numbers, then read the shape from them."},{title:"Apply to the stem",body:"Shape decides mean + SD (symmetric) or median + IQR (skewed); then report."}],final:"Order 2, 4, 1, 3 → answer **B**",whyWrong:["Incorrect — skewness and the mean–median gap come from the output, so the output comes first.","","Incorrect — the summary pair depends on the shape, so check shape before choosing.","Incorrect — choosing the pair before seeing the data skips the shape check."],bookRef:"Book pp. 147–151"},{id:"sv-2-997",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What does a Minitab **skewness** value close to zero indicate?",options:["The data are proven to be normal","The data contain no extreme values","The distribution is roughly symmetric","The distribution has light tails"],answer:2,hint:"Skewness measures asymmetry.",steps:[{title:"Key idea",body:"Skewness ≈ 0 → neither tail is longer → roughly symmetric."},{title:"Eliminate look-alikes",body:"Normality, outliers and tail weight need other evidence (normality test, kurtosis, graphs)."}],final:"Skewness ≈ 0 = symmetric → answer **C**",whyWrong:["Incorrect — symmetric data can still be flat, peaked or bimodal; skewness alone never proves normality.","Incorrect — symmetric data can have extreme values in both tails.","","Incorrect — tail weight is described by kurtosis, not skewness."],bookRef:"Book pp. 257–261"},{id:"sv-2-998",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Which of these statistics describes the **shape** of a distribution rather than its location or variation?",options:["Kurtosis","Median","Range","Variance"],answer:0,hint:"Location, variation — and shape.",steps:[{title:"Key idea",body:"Location: mean, median, mode. Variation: range, IQR, SD, variance."},{title:"Apply to the stem",body:"Skewness and **kurtosis** describe shape."}],final:"Kurtosis = shape → answer **A**",whyWrong:["","Incorrect — the median is a measure of location.","Incorrect — the range is a measure of variation.","Incorrect — the variance is a measure of variation."],bookRef:"Book pp. 257–261"},{id:"sv-2-999",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Why is the **standard deviation** usually reported instead of the variance when describing spread to a sponsor?",options:["Because standard deviations of independent sources can be added","Because it is resistant to extreme values","Because it is always smaller than the variance","Because it is in the same units as the data"],answer:3,hint:"Variance = squared units; SD = its square root.",steps:[{title:"Key idea",body:"The variance is in squared units (min², mm²), which are hard to picture."},{title:"Apply to the stem",body:"Taking the square root returns to the data units, so the SD is easier to interpret."}],final:"SD is in data units → answer **D**",whyWrong:["Incorrect — it is variances, not standard deviations, that add.","Incorrect — the SD uses every value, so extreme values affect it.","Incorrect — when the variance is below 1, the SD is larger than the variance.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-1000",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"The largest value in a set of 60 repair times is replaced by a value ten times larger. What happens to the **interquartile range**?",options:["It does not change","It increases a lot","It decreases","It becomes equal to the range"],answer:0,hint:"IQR = Q3 − Q1.",steps:[{title:"Key idea",body:"The largest value is in the top quarter, outside Q1–Q3."},{title:"Apply to the stem",body:"Q1 and Q3 do not move, so the IQR stays the same — it is resistant."}],final:"IQR unchanged → answer **A**",whyWrong:["","Incorrect — that happens to the range, the SD and the variance, not to the IQR.","Incorrect — making one value larger cannot shrink the spread of the middle 50%.","Incorrect — the IQR depends on Q1 and Q3 only, never on the extremes."],bookRef:"Book pp. 147–151"},{id:"sv-2-1001",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Minitab reports a **skewness of −2.1** for agent quality scores. What does this indicate?",options:["The data are strongly right-skewed, with a long tail of high scores","The data are strongly left-skewed, with a long tail of low scores","The data have lighter tails than a normal curve","The data are roughly symmetric"],answer:1,hint:"Sign of skewness = side of the long tail.",steps:[{title:"Key idea",body:"Negative skewness → long tail on the left (low values)."},{title:"Apply to the stem",body:"−2.1 is far from zero, so the left skew is strong."}],final:"Negative skewness = left tail → answer **B**",whyWrong:["Incorrect — right skew gives a positive skewness value.","","Incorrect — light tails are described by negative kurtosis, not negative skewness.","Incorrect — a value far from zero shows clear asymmetry."],bookRef:"Book pp. 257–261"},{id:"sv-2-1002",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Why are the median and the interquartile range described as **resistant** statistics?",options:["Because they use every value in the data set equally","Because they are calculated from squared deviations","Because they depend on the positions of the middle values, not on how extreme the end values are","Because they are always smaller than the mean and the standard deviation"],answer:2,hint:"Order-based statistics ignore how far the extremes are.",steps:[{title:"Key idea",body:"Median = middle position; IQR = Q3 − Q1, both based on sorted positions."},{title:"Apply to the stem",body:"An extreme value can grow without moving these positions, so they resist it."}],final:"Position-based → resistant → answer **C**",whyWrong:["Incorrect — using every value equally is why the mean and SD are not resistant.","Incorrect — squared deviations make the variance and SD more sensitive to extremes.","","Incorrect — resistance is about sensitivity to extremes, not about size."],bookRef:"Book pp. 147–151"},{id:"sv-2-1003",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Why is the **variance** very sensitive to an outlier?",options:["Because the variance is calculated from the median","Because the variance ignores the middle 50% of the data","Because the variance divides by n − 1","Because each deviation from the mean is squared, so a large deviation dominates"],answer:3,hint:"Squaring magnifies large deviations.",steps:[{title:"Key idea",body:"Variance = average squared deviation from the mean."},{title:"Apply to the stem",body:"A deviation 10 times larger contributes 100 times as much, so one outlier can dominate."}],final:"Squared deviations → sensitive → answer **D**",whyWrong:["Incorrect — the variance uses deviations from the mean, not from the median.","Incorrect — the variance uses every value; ignoring the middle half describes nothing standard.","Incorrect — the n − 1 divisor corrects for sampling; it does not cause the sensitivity.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-1004",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about the centre measures of a **right-skewed** distribution is CORRECT?",options:["The usual order from low to high is mode, then median, then mean","The usual order from low to high is mean, then median, then mode","The mean, median and mode are equal","The median is usually larger than both the mean and the mode"],answer:0,hint:"The tail drags the mean furthest; the mode stays at the peak.",steps:[{title:"Key idea",body:"Right skew: the peak (mode) is on the left, and the long right tail pulls the mean up."},{title:"Apply to the stem",body:"So mode < median < mean."}],final:"Right skew: mode < median < mean → answer **A**",whyWrong:["","Incorrect — that order belongs to a left-skewed distribution.","Incorrect — they coincide only for a symmetric, single-peaked distribution.","Incorrect — the median lies between the mode and the mean."],bookRef:"Book pp. 257–261"},{id:"sv-2-1005",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"Which statement about the **standard error of the mean (SE Mean)** is CORRECT?",options:["It describes the spread of the individual values around the mean","It is smaller than the standard deviation of the individual values whenever n is greater than 1","It increases as the sample size increases","It is the variance divided by the sample size"],answer:1,hint:"SE Mean = s divided by √n.",steps:[{title:"Key idea",body:"Dividing the SD by √n (greater than 1 for n > 1) gives a smaller number."},{title:"Eliminate look-alikes",body:"It describes the mean's precision, shrinks with n, and is the square root of variance ÷ n."}],final:"SE Mean < StDev for n > 1 → answer **B**",whyWrong:["Incorrect — the spread of individual values is the standard deviation.","","Incorrect — dividing by √n makes it shrink as n grows.","Incorrect — variance ÷ n is the square of the standard error, not the standard error itself."],bookRef:"Book pp. 147–151"},{id:"sv-2-1006",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

The standard [?] of the mean is the standard deviation divided by the square root of the sample size.`,options:["deviation","error","range","score"],answer:1,hint:"Minitab labels it SE Mean.",steps:[{title:"Key idea",body:"SE Mean = s ÷ √n: the standard **error** of the mean."},{title:"Apply to the stem",body:"It measures how precisely the sample mean estimates the population mean."}],final:"Standard error → answer **B**",whyWrong:["Incorrect — the standard deviation is the spread of the individual values.","","Incorrect — 'standard range' is not a statistic.","Incorrect — a standard score (Z-score) counts SDs from the mean."],bookRef:"Book pp. 147–151"},{id:"sv-2-1007",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

The third quartile, Q3, is the [?] percentile of the data.`,options:["25th","50th","75th","90th"],answer:2,hint:"Quartiles split the data into four quarters.",steps:[{title:"Key idea",body:"Q1 = 25th, median = 50th, Q3 = **75th** percentile."},{title:"Apply to the stem",body:"75% of the values lie at or below Q3."}],final:"Q3 = 75th percentile → answer **C**",whyWrong:["Incorrect — the 25th percentile is Q1.","Incorrect — the 50th percentile is the median.","","Incorrect — the 90th percentile is not a quartile."],bookRef:"Book pp. 147–151"},{id:"sv-2-1008",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:1,stem:"Which statistic is NOT expressed in the same units as the original data?",options:["Mean","Standard deviation","Variance","Interquartile range"],answer:2,hint:"One statistic squares the deviations.",steps:[{title:"Key idea",body:"Mean, SD and IQR are all in data units."},{title:"Apply to the stem",body:"The variance is in **squared** units."}],final:"Variance = squared units → answer **C**",whyWrong:["Incorrect — the mean is in data units.","Incorrect — the SD is the square root of the variance, which returns it to data units.","","Incorrect — the IQR is a difference of two data values, so it is in data units."],bookRef:"Book pp. 147–151"},{id:"sv-2-1009",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:1,stem:"Which of these is NOT based on the quartiles of the sorted data?",options:["Median","Interquartile range","Q1","Standard deviation"],answer:3,hint:"Quartile statistics come from sorted positions.",steps:[{title:"Key idea",body:"Q1, median (Q2), Q3 and the IQR all come from sorted positions."},{title:"Apply to the stem",body:"The **standard deviation** is built from deviations from the mean."}],final:"SD is mean-based → answer **D**",whyWrong:["Incorrect — the median is the second quartile (50th percentile).","Incorrect — the IQR is Q3 − Q1.","Incorrect — Q1 is the first quartile itself.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-1010",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:2,stem:"Which is NOT true of the **coefficient of variation**?",options:["It is resistant to extreme values","It expresses the standard deviation as a percentage of the mean","It has no units","It allows processes with different means to be compared"],answer:0,hint:"The CV is built from two non-resistant statistics.",steps:[{title:"Key idea",body:"CV = SD ÷ mean × 100%, so it is unit-free and comparable across processes."},{title:"Apply to the stem",body:"Both the SD and the mean react to extreme values, so the CV is **not** resistant."}],final:"CV is not resistant → answer **A**",whyWrong:["","Incorrect — this is true: CoefVar = StDev ÷ Mean, as a percentage.","Incorrect — this is true: dividing SD by mean cancels the units.","Incorrect — this is true: that is the main use of the CV."],bookRef:"Book pp. 147–151"},{id:"sv-2-1011",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:2,stem:"On a 10-point app-rating scale, most customers score 9 or 10, but a smaller group gives low scores from 1 to 5. Which Minitab skewness value is most plausible for these ratings?",options:["−1.6","0.0","+1.6","+3.0"],answer:0,hint:"Scores bunch at the top, so the tail points down.",steps:[{title:"Key idea",body:"Long tail of low values = left skew = negative skewness."},{title:"Apply to the stem",body:"Only **−1.6** has the negative sign."}],final:"Left tail → negative skewness → answer **A**",whyWrong:["","Incorrect — 0 means symmetric; here the low scores form a long tail on one side.","Incorrect — a positive value would need a long tail of high scores.","Incorrect — a large positive value would need a long tail of high scores."],bookRef:"Book pp. 257–261"},{id:"sv-2-1012",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:1,stem:"A logistics manager wants to promise a delivery time that **90% of orders** meet, based on last quarter's delivery data. Which statistic should the team look up?",options:["The mean plus the range","The 90th percentile","The third quartile","The median"],answer:1,hint:"A percentile is the value below which that % of data fall.",steps:[{title:"Key idea",body:"The p-th percentile has p% of the values at or below it."},{title:"Apply to the stem",body:"The time that 90% of orders meet is the **90th percentile**."}],final:"90% of orders → 90th percentile → answer **B**",whyWrong:["Incorrect — adding the range to the mean has no percentile meaning.","","Incorrect — Q3 is the 75th percentile, so only 75% of orders would meet it.","Incorrect — the median is met by only half of the orders."],bookRef:"Book pp. 147–151"},{id:"sv-2-1013",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:3,stem:"A Green Belt compares chat response time (mean 40 s, SD 12 s) with field-repair time (mean 30 h, SD 6 h). He concludes chat is more variable because its SD number is larger. Was this an appropriate action?",options:["Yes, because the process with the larger standard deviation is always more variable","Yes, because both standard deviations come from the same Minitab command","No, because the variances should be compared instead of the standard deviations","No, because the units and means differ, so relative variation such as the CV is needed"],answer:3,hint:"Different units → compare relative variation.",steps:[{title:"Key idea",body:"Raw SDs can only be compared when the units and scale match."},{title:"Apply to the stem",body:"The coefficient of variation expresses each SD as a % of its mean, removing units."}],final:"Different units → CV → answer **D**",whyWrong:["Incorrect — 12 s and 6 h are in different units, so the numbers cannot be compared directly.","Incorrect — using the same command does not make the units comparable.","Incorrect — variances in s² and h² are no more comparable than the SDs.",""],bookRef:"Book pp. 147–151"},{id:"sv-2-1014",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:2,stem:"A Green Belt samples 15 calls to estimate the variation of all calls. She calculates the variance by dividing the sum of squared deviations by **15**. Was this an appropriate action?",options:["Yes, because n is the number of values in the data","Yes, because dividing by n gives the sample variance","No, because sample data should be divided by n − 1","No, because the sum should be divided by the square root of n"],answer:2,hint:"Sample → n − 1; population → N.",steps:[{title:"Key idea",body:"The 15 calls are a sample used to estimate all calls."},{title:"Apply to the stem",body:"So the book's sample formula applies: divide by **n − 1**."}],final:"Sample → n − 1 → answer **C**",whyWrong:["Incorrect — dividing by n (N) is the population formula, used only for a whole population.","Incorrect — the sample variance divides by n − 1.","","Incorrect — √n appears in the standard error of the mean, not in the variance."],bookRef:"Book pp. 147–151"},{id:"sv-2-1015",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Minitab output for two samples of the same billing process:

\`\`\`
Descriptive Statistics: BillTime (min)

Sample    N   Mean  SE Mean  StDev
Small    25  31.40     1.60   8.00
Large   400  31.10     0.40   8.00
\`\`\`

Which conclusion is CORRECT?`,options:["The large sample shows less variation in individual bill times","The small sample estimates the mean more precisely because its SE Mean is larger","Individual bill times spread equally in both samples, but the large sample estimates the mean more precisely","The two samples come from different processes because their SE Means differ"],answer:2,hint:"StDev = individuals; SE Mean = precision of the mean.",steps:[{title:"Key idea",body:"Same StDev (8.00) → same spread of individual times."},{title:"Apply to the stem",body:"SE Mean = StDev ÷ √n, so the large sample's 0.40 means a more precise mean."}],final:"Larger n → smaller SE Mean → answer **C**",whyWrong:["Incorrect — StDev is 8.00 in both, so individual spread is the same.","Incorrect — a larger SE Mean means a less precise estimate of the mean.","","Incorrect — SE Mean differs because n differs; StDev and mean match closely."],bookRef:"Book pp. 147–151"},{id:"sv-2-1016",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Minitab output for 120 ticket-close times:

\`\`\`
Descriptive Statistics: CloseTime (h)

Variable     N   Mean  Minimum    Q1  Median     Q3  Maximum
CloseTime  120  7.420    3.200  4.10    5.00   9.80    30.50
\`\`\`

Which description of the shape is BEST supported?`,options:["Left-skewed: the lower quarter of values is much more spread out","Symmetric: the median lies halfway between the minimum and maximum","Symmetric: the mean and median are close enough to be treated as equal","Right-skewed: the upper quarter of values is much more spread out and the mean is above the median"],answer:3,hint:"Compare the gaps on each side of the median.",steps:[{title:"Key idea",body:"Median to Q3 and Q3 to maximum are much wider gaps than Q1 to median and minimum to Q1."},{title:"Apply to the stem",body:"A long upper tail and mean (7.42) > median (5.00) → right skew."}],final:"Long upper tail → right skew → answer **D**",whyWrong:["Incorrect — Q1 and the minimum sit close to the median; the long stretch is above Q3.","Incorrect — the median (5.0) is far below the midpoint of 3.2 and 30.5.","Incorrect — the mean is well above the median, a sign of right skew.",""],bookRef:"Book pp. 257–261"},{id:"sv-2-1017",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Which Minitab menu path runs an **Anderson-Darling** test and draws a normal probability plot?",options:["Stat > Basic Statistics > Normality Test","Stat > Basic Statistics > Display Descriptive Statistics","Graph > Histogram","Stat > Quality Tools > Gage Study"],answer:0,hint:"Book p. 155: the normality check in Minitab.",steps:[{title:"Key idea",body:"**Normality Test** gives the AD statistic, its p-value and a probability plot in one output."},{title:"Eliminate look-alikes",body:"The other paths summarise, plot or study the gauge."}],final:"Menu = Normality Test → answer **A**",whyWrong:["","Incorrect — Display Descriptive Statistics tabulates mean, SD and quartiles but gives no normality test.","Incorrect — a histogram shows the shape but gives no p-value.","Incorrect — a Gage Study assesses the measurement system, not the data's shape."],bookRef:"Book p. 155"},{id:"sv-2-1018",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Approximately what share of a normal distribution lies **above its mean**?",options:["50%","68%","95%","99.7%"],answer:0,hint:"The normal curve is symmetric about its mean.",steps:[{title:"Key idea",body:"Symmetry: the mean splits the curve into two equal halves."},{title:"Apply to the stem",body:"So half of the distribution, **50%**, lies above the mean."}],final:"Symmetric → 50% above the mean → answer **A**",whyWrong:["","Incorrect — about 68% lies within ±1σ of the mean, on both sides together.","Incorrect — about 95% lies within ±2σ of the mean.","Incorrect — about 99.7% lies within ±3σ of the mean."],bookRef:"Book p. 152"},{id:"sv-2-1019",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"What does the **empirical rule** allow a Green Belt to do without a Z table?",options:["Test whether the data come from a normal distribution","Quickly estimate the share of normal output within 1, 2 or 3 standard deviations of the mean","Calculate the exact proportion beyond any specification limit","Decide whether two process means are different"],answer:1,hint:"68 – 95 – 99.7 is a shortcut.",steps:[{title:"Key idea",body:"The rule gives approximate shares within ±1σ, ±2σ and ±3σ."},{title:"Apply to the stem",body:"It is a quick check that needs no table, but only for data that are roughly normal."}],final:"Empirical rule = quick estimate → answer **B**",whyWrong:["Incorrect — testing normality needs the Anderson-Darling test or a probability plot.","","Incorrect — exact proportions beyond a limit need a Z-score and the standard normal table.","Incorrect — comparing two means needs a hypothesis test such as the 2-sample t."],bookRef:"Book pp. 153–154"},{id:"sv-2-1020",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which Anderson-Darling **p-value** gives the strongest evidence that the data are NOT normal?",options:["0.003","0.048","0.210","0.870"],answer:0,hint:"H₀ = normal; the smaller the p-value, the stronger the evidence against H₀.",steps:[{title:"Key idea",body:"A small p-value means the observed departure would be unlikely if the data were normal."},{title:"Apply to the stem",body:"The smallest value, **0.003**, is the strongest evidence of non-normality."}],final:"Smallest p = strongest evidence → answer **A**",whyWrong:["","Incorrect — 0.048 also rejects normality at α = 0.05, but the evidence is weaker than at 0.003.","Incorrect — 0.210 is above 0.05, so we fail to reject normality.","Incorrect — 0.870 shows no evidence against normality."],bookRef:"Book pp. 155–156"},{id:"sv-2-1021",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"A normal process keeps the same mean but its standard deviation **doubles**. What happens to the **height of the peak** of its curve?",options:["It becomes higher, because more values are spread out","It stays the same, because only the mean sets the peak","It becomes lower, because the total area under the curve stays the same","It moves to the right, because a larger SD shifts the curve"],answer:2,hint:"The area under any normal curve is always 1 (100%).",steps:[{title:"Key idea",body:"A larger SD makes the curve wider."},{title:"Apply to the stem",body:"With the area fixed at 1, a wider curve must be **lower and flatter**."}],final:"Wider curve → lower peak → answer **C**",whyWrong:["Incorrect — spreading the same total area more widely must lower the curve, not raise it.","Incorrect — the SD changes both the width and the height of the curve.","","Incorrect — only a change in the mean moves the curve along the axis."],bookRef:"Book pp. 152–153"},{id:"sv-2-1022",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which pair of shape statistics would Minitab report for data that are **perfectly normal**?",options:["Skewness 0 and kurtosis 3","Skewness 1 and kurtosis 0","Skewness 3 and kurtosis 1","Skewness 0 and kurtosis 0"],answer:3,hint:"Normal = symmetric, with the reference tail shape.",steps:[{title:"Key idea",body:"Symmetric → skewness 0."},{title:"Apply to the stem",body:"Minitab's kurtosis is excess kurtosis, so the normal reference is also **0**."}],final:"Normal: skewness 0, kurtosis 0 → answer **D**",whyWrong:["Incorrect — 3 is the normal kurtosis only in the raw convention; Minitab reports excess kurtosis, so 0.","Incorrect — a skewness of 1 means a clear right tail; normal data are symmetric.","Incorrect — both values describe a strongly skewed, heavy-tailed shape.",""],bookRef:"Book pp. 257–261"},{id:"sv-2-1023",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Which graph does Minitab's **Normality Test** command draw with the Anderson-Darling result?",options:["A normal probability plot","A histogram with a fitted curve","A box plot","A run chart"],answer:0,hint:"Book p. 155: the two normality tools appear together.",steps:[{title:"Key idea",body:"The Normality Test output is a **normal probability plot** with AD and p-value printed beside it."},{title:"Apply to the stem",body:"Normal data fall on its straight line."}],final:"Normality Test → probability plot → answer **A**",whyWrong:["","Incorrect — a histogram with a fitted curve comes from the Graphical Summary or Graph > Histogram.","Incorrect — a box plot shows quartiles and outliers but is not part of the Normality Test output.","Incorrect — a run chart plots data in time order."],bookRef:"Book p. 155"},{id:"sv-2-1024",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Why are many physical measurements, such as machined diameters from a stable process, approximately **normal**?",options:["Because one large special cause dominates the variation","Because many small, independent random causes add together","Because the measurements are bounded at zero","Because the process is adjusted after every part"],answer:1,hint:"Book p. 151: normal output carries only random error.",steps:[{title:"Key idea",body:"With only random error, many small effects push values up or down."},{title:"Apply to the stem",body:"Their combined effect piles up symmetrically around the mean — a bell shape."}],final:"Many small random causes → normal → answer **B**",whyWrong:["Incorrect — a dominant special cause usually distorts the bell shape.","","Incorrect — a hard boundary near the data usually produces skew, not a bell.","Incorrect — constant adjustment adds variation and can distort the distribution."],bookRef:"Book pp. 151–152"},{id:"sv-2-1025",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about **symmetry and normality** is CORRECT?",options:["Any symmetric distribution follows the empirical rule","If the mean equals the median, the Anderson-Darling test will pass","A symmetric distribution is not necessarily normal","A normal distribution can have one long tail"],answer:2,hint:"Normal implies symmetric; symmetric does not imply normal.",steps:[{title:"Key idea",body:"Uniform, bimodal and heavy-tailed shapes can all be symmetric."},{title:"Apply to the stem",body:"So symmetry is necessary for normality but not enough on its own."}],final:"Symmetric ≠ normal → answer **C**",whyWrong:["Incorrect — a symmetric but flat or bimodal shape does not give 68–95–99.7.","Incorrect — symmetric data can still fail the AD test, for example when they are flat or heavy-tailed.","","Incorrect — a normal curve is symmetric, so it cannot have one long tail."],bookRef:"Book pp. 152, 155"},{id:"sv-2-1026",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"Which statement about a **stable, normally distributed** process is CORRECT?",options:["About 99.7% of its output lies within the specification limits","None of its output can fall beyond ±3σ of the mean","Its output is always capable because it is normal","About 99.7% of its output lies within ±3σ of the mean, whether or not that band fits inside the specification"],answer:3,hint:"The empirical rule is about μ ± kσ, not about specifications.",steps:[{title:"Key idea",body:"Normal and stable → about 99.7% within μ ± 3σ."},{title:"Apply to the stem",body:"Whether that band fits inside the spec is a separate capability question."}],final:"±3σ band ≠ spec limits → answer **D**",whyWrong:["Incorrect — the empirical rule refers to the process's own mean and σ, not to the customer's limits.","Incorrect — about 0.3% still falls beyond ±3σ; the tails never reach zero.","Incorrect — normality describes shape; capability depends on the spec limits.",""],bookRef:"Book pp. 153–154",trap:"Normal does not mean capable."},{id:"sv-2-1027",phase:2,topic:"2.2.3",qtype:"statements",difficulty:3,stem:`Consider these statements about the **Anderson-Darling test and sample size**:

1. Very large samples always pass the test.
2. Very small samples may fail to detect a real departure from normality.
3. Very large samples can flag departures too small to matter in practice.
4. The p-value does not depend on the sample size.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Sample size changes the power of the test.",steps:[{title:"Key idea",body:"Small n → low power → real departures may be missed (2 is true)."},{title:"Apply to the stem",body:"Large n → very sensitive → trivial departures give low p (3 is true; book p. 157)."},{title:"Eliminate look-alikes",body:"1 reverses the large-n effect; 4 ignores it."}],final:"2 and 3 are true → answer **B**",whyWrong:["Incorrect — statement 1 is false: large samples make the test reject more easily, not less.","","Incorrect — statement 4 is false: the same departure gives a smaller p-value as n grows.","Incorrect — both are false: large samples reject more readily, and the p-value depends on n."],bookRef:"Book p. 157"},{id:"sv-2-1028",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

According to the book, a process with normally distributed output is free of assignable causes and free of drifts and [?].`,options:["outliers","shifts","specifications","trends"],answer:1,hint:"Book p. 151: three characteristics.",steps:[{title:"Key idea",body:"Only random error; free of assignable causes; free of drifts and **shifts**."},{title:"Apply to the stem",body:"A drift slowly moves the centre; a shift moves it suddenly — both distort the bell."}],final:"Drifts and shifts → answer **B**",whyWrong:["Incorrect — the book's list is random error only, no assignable causes, no drifts and shifts.","","Incorrect — specifications are set by the customer; they do not affect the shape.","Incorrect — a trend is a kind of drift; the book pairs drifts with shifts."],bookRef:"Book p. 151"},{id:"sv-2-1029",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

The empirical rule for normal data is often called the [?] rule.`,options:["1.5 × IQR","68–95–99.7","80/20","n − 1"],answer:1,hint:"Name it after its three shares.",steps:[{title:"Key idea",body:"±1σ ≈ 68%, ±2σ ≈ 95%, ±3σ ≈ 99.7%."},{title:"Apply to the stem",body:"Hence the name **68–95–99.7** rule."}],final:"68–95–99.7 rule → answer **B**",whyWrong:["Incorrect — 1.5 × IQR is the box-plot rule for flagging outliers.","","Incorrect — 80/20 is the Pareto principle.","Incorrect — n − 1 is the divisor in the sample variance."],bookRef:"Book pp. 153–154"},{id:"sv-2-1030",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:2,stem:"Which of these is NOT a normality test?",options:["Anderson-Darling","Kolmogorov-Smirnov","Levene's test","Ryan-Joiner"],answer:2,hint:"One option tests a different assumption.",steps:[{title:"Key idea",body:"Minitab's Normality Test offers Anderson-Darling, Ryan-Joiner and Kolmogorov-Smirnov."},{title:"Apply to the stem",body:"**Levene's test** checks for equal variances between groups."}],final:"Levene's = equal variances → answer **C**",whyWrong:["Incorrect — Anderson-Darling is the book's normality test and Minitab's default.","Incorrect — Kolmogorov-Smirnov is one of the normality tests offered in Minitab.","","Incorrect — Ryan-Joiner is one of the normality tests offered in Minitab."],bookRef:"Book p. 155"},{id:"sv-2-1031",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:3,stem:"Each of these could explain a low Anderson-Darling p-value EXCEPT:",options:["The process mean is far from its target","Data from two different processes are mixed together","The gauge records values in coarse steps","A few special-cause outliers are present"],answer:0,hint:"Normality is about shape, not about location versus a target.",steps:[{title:"Key idea",body:"Mixtures, granularity and outliers all change the shape of the data."},{title:"Apply to the stem",body:"A mean far from target shifts the whole curve but leaves its shape — and the p-value — unchanged."}],final:"Off-target mean ≠ non-normal → answer **A**",whyWrong:["","Incorrect — mixed processes often give a bimodal shape that fails the test.","Incorrect — coarse resolution stacks the data in columns, which the AD test rejects.","Incorrect — special-cause outliers distort the tails and lower the p-value."],bookRef:"Book pp. 156–158"},{id:"sv-2-1032",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"A Green Belt wants **one** Minitab output for 64 shaft diameters that shows a histogram with a normal curve, the mean, SD, skewness and kurtosis, and the Anderson-Darling result. Which command should she use?",options:["Display Descriptive Statistics","Graphical Summary","Individual Value Plot","Run Chart"],answer:1,hint:"Stat > Basic Statistics > Graphical Summary.",steps:[{title:"Key idea",body:"The Graphical Summary combines a histogram with a fitted normal curve, a box plot, descriptive statistics and the AD test."},{title:"Eliminate look-alikes",body:"The other commands each give only part of this picture."}],final:"One output with everything = Graphical Summary → answer **B**",whyWrong:["Incorrect — Display Descriptive Statistics gives the numbers but no histogram or AD test.","","Incorrect — an individual value plot shows each point but no statistics or AD test.","Incorrect — a run chart shows the data over time, not the distribution."],bookRef:"Book pp. 155–156"},{id:"sv-2-1033",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"A team has confirmed that its gauge is acceptable and that fill weights pass the Anderson-Darling test (p = 0.47). The sponsor now asks how well the process meets the customer's limits. Which analysis comes next?",options:["A second Gage R&R study","A Pareto chart of fill weights","A capability analysis using the normal distribution","A chi-square test of fill weights"],answer:2,hint:"Normality checked → normal-based tools are allowed.",steps:[{title:"Key idea",body:"p = 0.47 > 0.05 → fail to reject normality → normal enough."},{title:"Apply to the stem",body:"Meeting customer limits is a **capability** question, which can now use the normal model."}],final:"Next = normal-based capability → answer **C**",whyWrong:["Incorrect — the gauge is already confirmed; repeating the MSA does not answer the spec question.","Incorrect — a Pareto chart ranks categories, not continuous fill weights.","","Incorrect — chi-square tests association between categorical variables."],bookRef:"Book pp. 156, 221"},{id:"sv-2-1034",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"A Green Belt lists four metrics. Which one is MOST likely to be approximately **normal**?",options:["Time to resolve a complaint, where most close in a day but some take months","First-contact resolution rate per agent, where most agents are near 100%","Weekly order counts mixed from two warehouses of very different size","Fill volume of bottles from a stable filling head"],answer:3,hint:"Look for random variation around a target with no boundary or mixture.",steps:[{title:"Key idea",body:"A stable filling head has only random variation around its set point."},{title:"Eliminate look-alikes",body:"Natural boundaries (0, 100%) cause skew; mixed sources cause two peaks."}],final:"Stable fill volume → normal → answer **D**",whyWrong:["Incorrect — times bounded at zero with a long right tail are usually right-skewed.","Incorrect — values piled up against a 100% ceiling give a left-skewed shape.","Incorrect — mixing two very different sources usually gives a bimodal shape.",""],bookRef:"Book pp. 151–154"},{id:"sv-2-1035",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:3,stem:"Hourly call-handling times pass the Anderson-Darling test (p = 0.52). The Green Belt concludes that the process is therefore **stable over time** and skips the control chart. Was this an appropriate action?",options:["Yes, because normal data can only come from a stable process","Yes, because a p-value above 0.05 confirms there are no special causes","No, because the normality test ignores time order, so stability must be checked on a control chart","No, because the p-value should have been below 0.05 to show stability"],answer:2,hint:"Shape and stability are different questions.",steps:[{title:"Key idea",body:"The AD test looks at the pooled values, not their order in time."},{title:"Apply to the stem",body:"Stability needs a time-ordered tool such as a control chart."}],final:"Normality ≠ stability → answer **C**",whyWrong:["Incorrect — shifts can occur in time order while the pooled data still look roughly normal.","Incorrect — failing to reject normality says nothing about special causes over time.","","Incorrect — a low p-value would mean non-normal data; stability is not judged by this test at all."],bookRef:"Book pp. 151, 155"},{id:"sv-2-1036",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:2,stem:'An Anderson-Darling test at α = 0.05 gives **p = 0.08** for invoice-processing times. A colleague says: "That is borderline, so let us call the data non-normal." What is the BEST response?',options:["Apply the rule: p is above α, so we fail to reject normality, and confirm with the probability plot","Agree, because any p-value below 0.10 means the data are not normal","Change α to 0.10 after seeing the result so that normality is rejected","Report that the data have been proven normal"],answer:0,hint:"Compare p with the α agreed beforehand.",steps:[{title:"Key idea",body:"p = 0.08 > α = 0.05 → fail to reject H₀ (data normal)."},{title:"Apply to the stem",body:"Use the plot to see whether any departure matters; do not move α after the fact."}],final:"p > α → fail to reject → answer **A**",whyWrong:["","Incorrect — at the agreed α = 0.05, a p-value of 0.08 does not reject normality.","Incorrect — changing α after seeing the result biases the decision.","Incorrect — a test never proves normality; it only fails to reject it."],bookRef:"Book pp. 155–156"},{id:"sv-2-1037",phase:2,topic:"2.2.3",qtype:"output",difficulty:3,stem:`Minitab output for 120 coating thicknesses:

\`\`\`
Normality Test: Thickness (µm)

N           120
Mean      50.02
Median    50.05
StDev      2.88
Skewness   0.02
Kurtosis  -1.31
AD         2.94
P-Value  <0.005
\`\`\`

Which conclusion is BEST supported?`,options:["The data are normal because the mean and median are almost equal","The data are symmetric but not normal; their flat, light-tailed shape needs investigating","The data are not normal because they are strongly right-skewed","The data are normal because the skewness is close to zero"],answer:1,hint:"Symmetric is not the same as normal.",steps:[{title:"Key idea",body:"p < 0.005 → reject H₀ → not normal."},{title:"Apply to the stem",body:"Skewness ≈ 0 but kurtosis −1.31 → symmetric and platykurtic; look for mixed streams or drift."}],final:"Symmetric but platykurtic → not normal → answer **B**",whyWrong:["Incorrect — equal mean and median show symmetry, not normality; p < 0.005 rejects normality.","","Incorrect — skewness 0.02 shows no skew; the problem is the flat shape (kurtosis −1.31).","Incorrect — near-zero skewness shows symmetry only; the AD test still rejects normality."],bookRef:"Book pp. 156–158"},{id:"sv-2-1038",phase:2,topic:"2.2.3",qtype:"output",difficulty:2,stem:`Minitab Graphical Summary for 64 shaft diameters:

\`\`\`
Summary Report for Diameter (mm)

Anderson-Darling Normality Test
  A-Squared    0.41
  P-Value     0.336
Mean         20.004
StDev         0.012
Skewness       0.12
Kurtosis      -0.20
N                64
\`\`\`

Which reading is CORRECT?`,options:["Kurtosis −0.20 shows the data are not normal","A-Squared 0.41 is below 0.05, so normality is rejected","P-Value 0.336 is above 0.05, so we fail to reject normality","Skewness 0.12 proves the data are normal"],answer:2,hint:"The p-value makes the normality decision.",steps:[{title:"Key idea",body:"Compare the AD **P-Value** with α = 0.05."},{title:"Apply to the stem",body:"0.336 > 0.05 → fail to reject H₀ → normal enough; the shape statistics agree."}],final:"Read the P-Value → fail to reject → answer **C**",whyWrong:["Incorrect — a kurtosis of −0.20 is close to the normal value of 0; the decision uses the p-value.","Incorrect — the decision compares the p-value, not A-Squared, with α.","","Incorrect — skewness shows rough symmetry only; nothing proves normality."],bookRef:"Book pp. 155–156"},{id:"sv-2-1039",phase:2,topic:"2.2.3",qtype:"sequence",difficulty:2,stem:`For normally distributed data, put these intervals in order from the **smallest** share of values to the **largest**.

1. Mean ± 2σ
2. Between Q1 and Q3
3. Mean ± 3σ
4. Mean ± 1σ

What is the correct order?`,options:["4, 2, 1, 3","2, 4, 3, 1","4, 1, 2, 3","2, 4, 1, 3"],answer:3,hint:"Q1–Q3 = 50% for any data; then 68 – 95 – 99.7.",steps:[{title:"Key idea",body:"Between Q1 and Q3 lies the middle 50% of any data set."},{title:"Apply to the stem",body:"For normal data: ±1σ ≈ 68%, ±2σ ≈ 95%, ±3σ ≈ 99.7%."}],final:"Order 2, 4, 1, 3 → answer **D**",whyWrong:["Incorrect — ±1σ holds about 68%, which is more than the 50% between Q1 and Q3.","Incorrect — ±3σ (99.7%) holds more than ±2σ (95%).","Incorrect — Q1 to Q3 holds 50%, less than ±1σ and ±2σ.",""],bookRef:"Book pp. 150, 153–154"},{id:"sv-2-1040",phase:2,topic:"2.2.3",qtype:"output",difficulty:3,stem:`A team checked 500 latency readings against the empirical rule:

\`\`\`
Share of readings within Mean ± k × StDev

k   Observed %   Expected % (normal)
1        78.4         68.3
2        93.0         95.4
3        97.6         99.7
\`\`\`

Which conclusion is BEST supported?`,options:["The data do not follow the empirical rule: they are more peaked, with more extreme values than a normal curve","The data follow the empirical rule closely, so they are normal","The data are flatter than a normal curve, with fewer extreme values","The data must be left-skewed because fewer readings lie within ±2σ"],answer:0,hint:"Compare the observed shares with 68 – 95 – 99.7.",steps:[{title:"Key idea",body:"Too many readings in the centre (78% vs 68%) and too many beyond ±3σ (2.4% vs 0.3%)."},{title:"Apply to the stem",body:"That pattern is a sharp peak with heavy tails — not normal."},{title:"Eliminate look-alikes",body:"The table is symmetric about the mean, so it says nothing about skew direction."}],final:"Peaked and heavy-tailed → not normal → answer **A**",whyWrong:["","Incorrect — 78% within ±1σ and only 97.6% within ±3σ are well away from 68% and 99.7%.","Incorrect — a flat shape would put fewer values near the centre, not 78% within ±1σ.","Incorrect — the table covers both sides at once, so it cannot show the direction of skew."],bookRef:"Book pp. 153–154"}];export{e as items};
